"""KAT-648 T-005 Step 6 — overlay_values.py writes an overlay's environment.env
from Terraform's outputs, so no identifier is typed twice (ARD-059 §3, §8)."""
import io
import json
import pathlib
import sys
import tempfile
import unittest
from contextlib import redirect_stdout

HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent))

import overlay_values  # noqa: E402

OUTPUTS = HERE / "fixtures" / "outputs-staging.json"

EXPECTED = """\
# Generated by IaC/scripts/overlay_values.py from `terraform output` of envs/staging.
# Do not edit: change Terraform, apply it, and run the script again (ARD-059 §3, §8).
REGISTRY=katachistgabcde.azurecr.io
APP_HOST=staging.example.test
MCP_HOST=mcp.staging.example.test
ADMIN_HOST=admin.staging.example.test
TRUSTED_PROXY_CIDR=10.244.0.0/16
KEY_VAULT_NAME=kat-stg-app-abcde
ADMIN_KEY_VAULT_NAME=kat-stg-adm-abcde
AZURE_TENANT_ID=00000000-0000-0000-0000-000000000001
CLIENT_ID_BACKEND=11111111-0000-0000-0000-000000000001
CLIENT_ID_WORKER=11111111-0000-0000-0000-000000000002
CLIENT_ID_SCHEDULER=11111111-0000-0000-0000-000000000003
CLIENT_ID_MCP=11111111-0000-0000-0000-000000000004
CLIENT_ID_MIGRATE=11111111-0000-0000-0000-000000000006
CLIENT_ID_REDIS=11111111-0000-0000-0000-000000000007
CLIENT_ID_DB_BOOTSTRAP=11111111-0000-0000-0000-000000000005
DB_MAX_USER_CONNECTIONS=414
DB_ADMIN_USER=katachiadmin
AZURE_SUBSCRIPTION_ID=22222222-0000-0000-0000-000000000001
CLUSTER_NAME=katachi-staging-aks
CLUSTER_RESOURCE_GROUP=katachi-staging
PIPELINE_CLIENT_ID=33333333-0000-0000-0000-000000000001
PIPELINE_PRINCIPAL_ID=44444444-0000-0000-0000-000000000001
SMTP_HOST=smtp.azurecomm.net
SMTP_USERNAME=katachi-staging-mail.55555555-0000-0000-0000-000000000001.00000000-0000-0000-0000-000000000001
MAIL_FROM=donotreply@staging.example.test
POSTGRES_SERVER_NAME=katachi-staging-pg-abcde
POWER_CLIENT_ID=66666666-0000-0000-0000-000000000001
"""


class Overlay(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.tcm = pathlib.Path(self.tmp.name) / "tcm"
        (self.tcm / "k8s" / "overlays" / "staging").mkdir(parents=True)
        self.env_file = self.tcm / "k8s" / "overlays" / "staging" / "environment.env"

    def tearDown(self):
        self.tmp.cleanup()

    def run_script(self, *extra, outputs=None, env="staging"):
        path = OUTPUTS
        if outputs is not None:
            path = pathlib.Path(self.tmp.name) / "outputs.json"
            path.write_text(json.dumps(outputs))
        out = io.StringIO()
        with redirect_stdout(out):
            code = overlay_values.main([env, "--outputs", str(path), "--tcm", str(self.tcm), *extra])
        return code, out.getvalue()

    def outputs(self):
        return json.loads(OUTPUTS.read_text())

    def test_writes_every_key_in_order(self):
        code, out = self.run_script()
        self.assertEqual(code, 0, out)
        self.assertEqual(self.env_file.read_text(), EXPECTED)

    def test_an_environment_with_no_switch_has_no_power_client_id(self):
        """KAT-648 T-005: only staging is turned off on a schedule; production's file
        names no such identity rather than an empty one."""
        outputs = json.loads(OUTPUTS.read_text())
        outputs["power_client_id"]["value"] = None
        path = pathlib.Path(self.tmp.name) / "outputs-no-power.json"
        path.write_text(json.dumps(outputs))
        self.assertEqual(overlay_values.main(["staging", "--outputs", str(path), "--tcm", str(self.tcm)]), 0)
        written = (self.tcm / "k8s" / "overlays" / "staging" / "environment.env").read_text()
        self.assertNotIn("POWER_CLIENT_ID", written)
        self.assertIn("POSTGRES_SERVER_NAME=katachi-staging-pg-abcde", written)

    def test_refuses_an_overlay_that_does_not_exist(self):
        code, out = self.run_script(env="production")
        self.assertEqual(code, 2)
        self.assertIn("T-002", out)
        self.assertFalse((self.tcm / "k8s" / "overlays" / "production").exists())

    def test_refuses_an_unknown_environment(self):
        code, _ = self.run_script(env="dev")
        self.assertEqual(code, 2)

    def test_refuses_a_missing_output(self):
        outputs = self.outputs()
        del outputs["pod_cidr"]
        code, out = self.run_script(outputs=outputs)
        self.assertEqual(code, 2)
        self.assertIn("pod_cidr", out)
        self.assertFalse(self.env_file.exists())

    def test_refuses_an_empty_output(self):
        outputs = self.outputs()
        outputs["key_vault_name"]["value"] = ""
        code, out = self.run_script(outputs=outputs)
        self.assertEqual(code, 2)
        self.assertIn("key_vault_name", out)

    def test_refuses_a_unit_with_no_client_id(self):
        outputs = self.outputs()
        del outputs["unit_client_ids"]["value"]["scheduler"]
        code, out = self.run_script(outputs=outputs)
        self.assertEqual(code, 2)
        self.assertIn("scheduler", out)

    def test_refuses_a_placeholder(self):
        outputs = self.outputs()
        outputs["app_host"]["value"] = "REPLACE-staging-app-host"
        code, out = self.run_script(outputs=outputs)
        self.assertEqual(code, 2)
        self.assertIn("app_host", out)

    def test_refuses_a_value_that_would_break_the_file(self):
        outputs = self.outputs()
        outputs["mcp_host"]["value"] = "mcp.staging.example.test\nREGISTRY=evil.example"
        code, out = self.run_script(outputs=outputs)
        self.assertEqual(code, 2)
        self.assertIn("mcp_host", out)

    def test_refuses_a_sensitive_output(self):
        outputs = self.outputs()
        outputs["tenant_id"]["sensitive"] = True
        code, out = self.run_script(outputs=outputs)
        self.assertEqual(code, 2)
        self.assertIn("tenant_id", out)

    def test_refuses_a_connection_limit_that_is_not_a_count(self):
        outputs = self.outputs()
        outputs["postgres_max_user_connections"]["value"] = 0
        code, _ = self.run_script(outputs=outputs)
        self.assertEqual(code, 2)

    def test_check_passes_a_current_file(self):
        self.run_script()
        code, out = self.run_script("--check")
        self.assertEqual(code, 0, out)

    def test_check_names_what_went_stale_and_writes_nothing(self):
        self.run_script()
        self.env_file.write_text(EXPECTED.replace("KEY_VAULT_NAME=kat-stg-app-abcde", "KEY_VAULT_NAME=typed-by-hand"))
        code, out = self.run_script("--check")
        self.assertEqual(code, 1)
        self.assertIn("KEY_VAULT_NAME", out)
        self.assertIn("typed-by-hand", self.env_file.read_text())


if __name__ == "__main__":
    unittest.main()
